import{describe,it,expect}from"vitest";import{photographyLocations,getFilteredLocations}from"../../frontend/photography-locations/photography-locations.js";describe("Photography Locations Explorer",()=>{it("has minimum 10 locations with required metadata fields",()=>{expect(Array.isArray(photographyLocations)).toBe(!0),expect(photographyLocations.length).toBeGreaterThanOrEqual(10),photographyLocations.forEach(e=>{expect(e.id).toBeDefined(),expect(e.name).toBeDefined(),expect(e.location).toBeDefined(),expect(e.season).toBeDefined(),expect(e.timeOfDay).toBeDefined(),expect(e.tip).toBeDefined(),expect(Array.isArray(e.gear)).toBe(!0)})}),it("filters by season correctly",()=>{const e=getFilteredLocations("","winter","all");expect(e.length).toBeGreaterThan(0),e.forEach(e=>expect(e.season).toBe("winter"))}),it("filters by time of day correctly",()=>{const e=getFilteredLocations("","all","sunrise");expect(e.length).toBeGreaterThan(0),e.forEach(e=>expect(e.timeOfDay).toBe("sunrise"))}),it("searches by location name",()=>{const e=getFilteredLocations("Varanasi");expect(e.length).toBeGreaterThan(0),expect(e[0].name.toLowerCase()).toContain("varanasi")}),it("covers all four season categories",()=>{const e=new Set(photographyLocations.map(e=>e.season));expect(e.has("winter")).toBe(!0),expect(e.has("monsoon")).toBe(!0),expect(e.has("spring")).toBe(!0),expect(e.has("autumn")).toBe(!0)})});